/**
* create the chatGPT question
* @param {string} GPTNodesStructure - nodes in the form of Chat GPT Structure
* @param {string} researchQuestion 
* @returns a string ready for OpenAI to ingest 
*/
async function createPrompt(GPTNodesStructure, researchQuestion) {
    // console.log(`${_module}/createPrompt @params GPTNodesStructure length`, GPTNodesStructure.length)
    // console.log(`${_module}/createPrompt @params researchQuestion`, researchQuestion)
    // var temp = `You are an expert in causal reasoning. 
    // You are using your knowledge to help build a causal model that contains all the assumptions about the factors that are directly influencing and causing the ${effect}. 
    // Where a causal model is a conceptual model that describes the causal mechanisms of a system. You will do this by by answering questions about cause and effect and using your domain knowledge as an expert in causal reasoning. 
    // From your perspective as an expert in causal reasoning which of the following factors has a high likelihood of directly influencing and causing the ${factor}? factors list: [${factors_list}] 
    // For any factors within the list with a high likelihood of directly influencing and causing the ${effect} wrap the name of the factor with the tags <influencing_factor>factor_name</influencing_factor>. 
    // If a factor does not have a high likelihood of directly influencing and causing the ${effect}, then do not wrap the factor with any tags. Your answer as an expert in causal reasoning.`
    // console.log(`${_module}/createPrompt temp`, temp)

    var question = `Given the following research question:\n\n${researchQuestion}\n\n`
    //         Suggest similar research questions considering counterfactual analysis and actual causality.
    if (GPTNodesStructure.length == 0) {
        question += `Identify the subject of the research question as the effect and provide a comprehensive list of causal assumptions related to the research question.\n`
    } else {
        question += `and the following existing causal model (DAG) in the form <cause>VariableA<cause>--><effect>VariableB<effect>, are there any other causal relationships that are relevant to the research question or anything that would affect the existing causal variables, consider multiple levels of relationships in your answer:\n\n`
        question += `Causal Model: ${GPTNodesStructure} \n\n`
        question += `Identify the subject of the research question as the effect and provide a comprehensive list of causal assumptions answering the research question.\n`
    }
    // `in the form of a DAG using graphviz minimal syntax ensuring that causes be on the left hand side and that effects be on the right hand side of each relation.`
    console.log(`${_module}/createPrompt question`, question)
    return question
}

/**
 * format causal model ready for chatGPT, format [a] --> [b]
 * @param {object} nodes - 
 * @returns 
 */

async function createGPTNodeStructure(nodes) {
    try {
        // console.log(`${_module}/createGPTNodeStructure`)
        // console.log(`${_module}/createGPTNodeStructure @param nodes`, nodes)
        if (nodes === undefined) { return [] }
        // start by getting all the nodes without children
        var rightNodes = []
        var chatGPTOutput = ""
        nodes.forEach((node) => {
            if (!node.hasOwnProperty("wires")) {
                // console.log(`${_module}/createGPTNodeStructure ${node.name} has no wires`)
                rightNodes.push(node)

            }
        })
        // recursive scan of nodes - right to left
        var leftNodes
        while (rightNodes.length > 0) {
            leftNodes = []
            rightNodes.forEach((effectNode) => {
                nodes.forEach((node) => {
                    // check against all nodes with wires
                    if (node.hasOwnProperty("wires")) {
                        if (
                            node.wires[0].filter((value) => effectNode.id.includes(value))
                                .length > 0
                        ) {
                            chatGPTOutput +=
                                "<cause>" + node.name + "<cause> --> <effect>" + effectNode.name + "<effect>, "
                            leftNodes.push(node)
                        }
                    }
                })

            })
            rightNodes = leftNodes
        }

        return chatGPTOutput.replace(/,\s*$/, "") // remove trailing comma and whitespace
    } catch (exception) {
        throw exception
    }
}


/**
 * Store api key
 * @param {object} req - request object containing api key
 * @param {object} res - response object containing response
 */
async function storeApiKey(req, res) {
    let _fn = `storeApiKey`
    try {
        if (req.body.activeWorkspace == 0) {
            res.send(200)
            return
        } else {
            console.log(`${_module} ${_fn} body keys`, Object.keys(req.body))
            let workspace = await getWorkspaceContext(req)
            console.log(`${_module} ${_fn} workspace`, Object.keys(workspace))
            console.log(`${_module} ${_fn} workspace`, workspace.hasOwnProperty("gpt_api_key"))
            let _temp = ""

            if (workspace.hasOwnProperty("gpt_api_key")) {
                console.log(`${_module} ${_fn} workspace`, workspace["gpt_api_key"])
                _temp = workspace["gpt_api_key"]
                    = delete workspace["gpt_api_key"]
                console.log(`${_module} ${_fn} deleted old key `, Object.keys(workspace))
            }
            if (workspace.hasOwnProperty("llm_api_key")) {
                console.log(`${_module} ${_fn} workspace`, workspace["gpt_api_key"])
                _temp = workspace["llm_api_key"]
                delete workspace["llm_api_key"]
                console.log(`${_module} ${_fn} deleted old key `, Object.keys(workspace))
            }

            // store in context
            workspace = { ...workspace, "llm_api_key": req.body.llm_api_key }
            workspace["llm_api_key"] = _temp === req.body.llm_api_key ? _temp : req.body.llm_api_key
            console.log(`${_module} ${_fn} added new key`, Object.keys(workspace))

            // delete old context key
            console.log(`${_module} ${_fn} workspace attributes`, Object.keys(workspace))
            let updatedFlow = await updateWorkspaceContext(req.body.activeWorkspace, workspace)
            console.log(`${_module} ${_fn} llm api key `, workspace["llm_api_key"])

            console.log("active workspace ", req.body.activeWorkspace)
            // actually update TypeDB with new key --- attribute gpt_api_key is being update
            let opts = {
                "db": "causeway-repo",
                "query": `match $gpt_info isa gpt_info, has nrid \"${req.body.activeWorkspace}\", has gpt_api_key $key; get $key;`,
                "query_type": "match",
                "session_type": "DATA",
                "transaction_type": "READ"
            }
            let _result = await typedbApi.executeQuery(opts)
            console.log(`${_module} ${_fn} _result  ${_result.length} `)
            opts["transaction_type"] = "WRITE"
            // insert - update  attribute
            if (_result.length === 0) {
                console.log(`${_module} ${_fn} inserting attribute`)
                opts["query_type"] = "insert"
                opts["query"] = `match $gpt_info isa gpt_info, has nrid \"${req.body.activeWorkspace}\";\ninsert $gpt_info has gpt_api_key  \"${workspace["llm_api_key"]}\";`
            } else {
                console.log(`${_module} ${_fn} updating attribute gpt_api_key`)
                opts["query_type"] = "update"
                opts["query"] = `match $gpt_info isa gpt_info, has nrid \"${req.body.activeWorkspace}\", has gpt_api_key $key;\n delete $gpt_info has $key;\ninsert $gpt_info has gpt_api_key \"${workspace["llm_api_key"]}\";`
            }
            await typedbApi.executeQuery(opts)
            console.log(`${_module} ${_fn} update_gpt_info for api_key successful ${String.fromCharCode(0x2611)} `)
            res.status(200).send({ updatedFlow: updatedFlow })
            return
        }
    } catch (exception) {
        // console.log(`${_module} exception `, exception)
        console.log(`${_module} ${_fn} Exception ${String.fromCharCode(0x274C)} ${exception}`)
        res.status(500).send({ error: exception })
    }
}


/**
 * Store api key
 * @param {object} req - request object containing api key
 * @param {object} res - response object containing response
 */
async function fetchApiKey(modelId) {
    let _fn = `fetchApiKey`
    try {
        if (modelId == 0) {
            return
        } else {
            let match_gpt_info = `match $gpt_info isa gpt_info, has nrid \"${modelId}\"; get $gpt_info;`
            let opts = {
                "db": "causeway-repo",
                "query": match_gpt_info,
                "query_type": "match",
                "session_type": "DATA",
                "transaction_type": "READ"
            }
            let query_result = await typedbApi.executeQuery(opts)
            // console.log(`${_module} [ getPromptInfo ] query_result`, query_result, typeof query_result, query_result.length)
            let llminfo = ["", ""]
            let keys = new Set(_previus_llm_ctx_keys)
            if (query_result.length !== 0) {
                let transaction = await typedbApi.create_transaction(opts.transaction_type)
                let _gpt_info = query_result[0].get("gpt_info").asRemote(transaction)
                let _gpt_info_attributes = await _gpt_info.getHas().collect()
                for await (let attribute of _gpt_info_attributes) {
                    let _label = attribute.type.label.name
                    let attr_value = attribute.value
                    if (keys.has(_label)) {
                        if (_label === "gpt_api_key") { llminfo[0] = attr_value }
                    }
                }
                await typedbApi.close_transaction(opts.transaction_type, transaction)
            }
            return llminfo
        }
    } catch (exception) {
        // console.log(`${_module} exception `, exception)
        throw exception
    }
}
/**
 * Load prompt for causal diagrams
 * @param {object} req - request object contains activeWorkspace, nodes, etc
 * @param {object} res - response object contains formulated prompt
 */
async function loadPrompt(req, res) {
    let _fn = `loadPrompt`
    try {
        let prompt = ""
        if (req.body.activeWorkspace == 0) {
            res.status(200).send({ prompt: prompt })
            return
        } else {
            let nodes = req.body.nodes
            let researchQuestion = req.body.researchQuestion
            let prompt = ""
            let workspace = await getWorkspaceContext(req)
            console.log(`${_module} ${_fn} workspace attributes`, Object.keys(workspace))

            let causal_graph = await createGPTNodeStructure(nodes)
            console.log(`${_module} ${_fn} causal graph`, causal_graph)

            workspace["gpt_research_question"] = workspace["gpt_research_question"] === undefined ? "" : workspace["gpt_research_question"]
            workspace["gpt_research_question"] = workspace["gpt_research_question"] !== researchQuestion ? researchQuestion : workspace["gpt_research_question"]
            prompt = await createPrompt(GPTNodesStructure = causal_graph, researchQuestion = workspace["gpt_research_question"], effect = req.body.outcome, factor = req.body.treatment, factors_list = nodes)
            console.log(`${_module} ${_fn} prompt`, prompt)

            workspace["gpt_prompt"] = prompt
            let updatedFlow = await updateWorkspaceContext(req.body.activeWorkspace, workspace)
            console.log(`${_module} ${_fn} updated flow`, Object.keys(updatedFlow))

            res.status(200).send({ prompt: prompt, updatedFlow: updatedFlow })
            return
        }
    } catch (exception) {
        console.log(`${_module} exception `, exception)
        res.status(500).send({ error: exception })
    }
}

